css:
/* Sangria: o Frappe força 15mm quando o formato vem com zero, e a arte azul
   precisa encostar nas bordas. Ele lê estas quatro propriedades quando
   aplicadas SÓ em `.print-format` (frappe/utils/pdf.py) e elas vencem o padrão. */
.print-format {
  margin-top: 0mm;
  margin-bottom: 0mm;
  margin-left: 0mm;
  margin-right: 0mm;
  padding: 0 !important;
}

/* IMPORTANTE: todo espaçamento de parágrafo abaixo é prefixado por
   `.print-format`. O CSS base do Frappe traz `.print-format p { margin: 3px }`,
   que tem especificidade maior que uma classe sozinha — sem o prefixo, ele
   apaga os espaços e a carta sai comprimida. */

.carta-proposta {
  position: relative;
  width: 100%;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}

/* A imagem tem a proporção do A4: a altura vem sozinha da largura. */
.cp-fundo {
  position: absolute;
  /* Ampliada 0,3% e recuada meio décimo para fora: a arte tem 1px sem cor no
     topo (0,3mm nesta resolução), e sem isso sobra um fio branco na borda
     superior do papel. A altura fecha exatamente na borda inferior: passar
     disso empurra o excedente para uma segunda página. A distorção é de 0,3% — invisível. */
  top: -0.5mm; left: 0;
  width: 100%; height: 297.5mm;
  z-index: 0;
}

/* Com a página sem margem, o recuo do texto vive aqui. */
.print-format .cp-conteudo {
  position: relative;
  z-index: 1;
  padding: 17mm 29mm 20mm 29mm;
  font-size: 11pt;
  line-height: 1.6;
}

/* Título e ID alinham a borda direita com o resto do texto. Parecem
   centralizados por causa da faixa azul à esquerda, mas medindo as bordas
   todas terminam no mesmo ponto. */
.print-format .cp-titulo { text-align: right; font-size: 19pt; font-weight: bold; line-height: 1.15; margin: 0; }
.print-format .cp-id     { text-align: right; font-size: 9pt; font-weight: bold; margin: 2mm 0 0 0; }

.print-format .cp-direita     { text-align: right; margin: 0; }
.print-format .cp-local       { margin-top: 20mm; }
.print-format .cp-saudacao    { margin-top: 7mm; }
.print-format .cp-texto       { text-align: justify; margin: 15mm 0 0 0; }
.print-format .cp-apos-tabela { margin-top: 13mm; }
.print-format .cp-assinatura  { margin-top: 24mm; }
.print-format .cp-equipe      { margin-top: 4mm; }

.print-format .cp-termos {
  margin: 13mm 0 0 0;
}

/* Uma linha por termo: rótulo em negrito, valor logo à frente. O recuo entre
   linhas é próprio, menor que o dos parágrafos do corpo, para o bloco ler
   como uma lista e não como texto solto. */
.print-format .cp-linha {
  margin: 0 0 2mm 0;
  /* Um valor longo (Small Text aceita várias linhas) quebra sem estourar. */
  word-wrap: break-word;
  overflow-wrap: break-word;
}
